static double lt_float_literal(const char *text) { return strtod(text, NULL); }
/* Split printf's positive finite decimal into significant digits and its first-digit exponent. */
static int lt_float_digits(const char *text, char *digits, int *exponent) {
    int size = 0, before = 0, dot = 0;
    const char *at = text;
    while (*at && *at != 'e' && *at != 'E') {
        if (*at == '.') dot = 1;
        else {
            digits[size++] = *at;
            if (!dot) before++;
        }
        at++;
    }
    int power = *at ? (int)strtol(at + 1, NULL, 10) : 0;
    int leading = 0;
    while (leading + 1 < size && digits[leading] == '0') leading++;
    memmove(digits, digits + leading, (size_t)(size - leading));
    size -= leading;
    digits[size] = '\0';
    *exponent = before - leading - 1 + power;
    return size;
}
/* Move to the adjacent positive decimal having at most precision significant digits. */
static void lt_float_neighbor(char *digits, int precision, int *exponent, int direction) {
    int at = precision - 1;
    if (direction > 0) {
        while (at >= 0 && digits[at] == '9') digits[at--] = '0';
        if (at >= 0) digits[at]++;
        else {
            digits[0] = '1';
            (*exponent)++;
        }
    } else {
        while (at >= 0 && digits[at] == '0') digits[at--] = '9';
        if (at >= 0) digits[at]--;
        if (digits[0] == '0') {
            for (int i = 0; i < precision; i++) digits[i] = '9';
            (*exponent)--;
        }
    }
}
/* Find the least significant-digit count that round-trips, including asymmetric boundary candidates. */
static int lt_float_format(double value, char *out) {
    if (value == 0.0) {
        strcpy(out, "0");
        return 1;
    }
    int negative = value < 0.0;
    double positive = negative ? -value : value;
    char digits[32], nearest[64], adjacent[64];
    int size = 0, exponent = 0, found = 0;
    for (int precision = 1; precision <= 17 && !found; precision++) {
        if (snprintf(nearest, sizeof nearest, "%.*g", precision, positive) < 0) return 0;
        size = lt_float_digits(nearest, digits, &exponent);
        if (strtod(nearest, NULL) == positive) {
            found = 1;
            break;
        }
        while (size < precision) digits[size++] = '0';
        digits[size] = '\0';
        for (int direction = -1; direction <= 1 && !found; direction += 2) {
            char candidate[32]; memcpy(candidate, digits, (size_t)size + 1);
            int power = exponent;
            lt_float_neighbor(candidate, precision, &power, direction);
            if (snprintf(adjacent, sizeof adjacent, "%se%d", candidate, power - precision + 1) < 0) return 0;
            if (strtod(adjacent, NULL) == positive) {
                memcpy(digits, candidate, (size_t)size + 1); exponent = power; found = 1;
            }
        }
    }
    if (!found) return 0;
    while (size > 1 && digits[size - 1] == '0') size--;
    int at = 0;
    if (negative) out[at++] = '-';
    if (exponent >= 21 || exponent < -6) {
        out[at++] = digits[0];
        if (size > 1) {
            out[at++] = '.';
            memcpy(out + at, digits + 1, (size_t)size - 1);
            at += size - 1;
        }
        out[at++] = 'e';
        if (exponent >= 0) out[at++] = '+';
        int length = snprintf(out + at, 64u - (size_t)at, "%d", exponent);
        if (length < 0) return 0;
        at += length;
    } else if (exponent < 0) {
        out[at++] = '0'; out[at++] = '.';
        for (int i = -1; i > exponent; i--) out[at++] = '0';
        memcpy(out + at, digits, (size_t)size); at += size;
    } else {
        for (int i = 0; i <= exponent || i < size; i++) {
            if (i == exponent + 1) out[at++] = '.';
            out[at++] = i < size ? digits[i] : '0';
        }
    }
    out[at] = '\0';
    return 1;
}
